from flask import Flask, jsonify, request

app = Flask(__name__)


def error_response(status, message, field=None):
    payload = {"error": {"status": status, "message": message}}
    if field is not None:
        payload["error"]["field"] = field
    return jsonify(payload), status


@app.post("/api/v1/tasks")
def create_task():
    data = request.get_json(silent=True)
    if data is None:
        return error_response(400, "тело запроса должно быть валидным JSON")
    title = data.get("title", "")
    if not isinstance(title, str) or not title.strip():
        return error_response(422, "заголовок не может быть пустым", field="title")
    return jsonify({"id": 1, "title": title.strip(), "done": False}), 201


app.run(debug=True)

